import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.ThreadFactory;
import java.util.concurrent.atomic.AtomicInteger;

public final class ConcurrencyConfig {

    public static ThreadPoolExecutor createIoBoundThreadPool() {
        int cores = Runtime.getRuntime().availableProcessors();
        // Assuming an average wait-to-compute ratio of 4:1
        int optimalThreads = cores * 2 * (1 + 4);

        return new ThreadPoolExecutor(
            cores * 2, 
            optimalThreads,
            60L, TimeUnit.SECONDS,
            new ArrayBlockingQueue<>(1000),
            new NamedThreadFactory("io-pool-worker"),
            new ThreadPoolExecutor.CallerRunsPolicy()
        );
    }

    private static class NamedThreadFactory implements ThreadFactory {
        private final String prefix;
        private final AtomicInteger counter = new AtomicInteger(1);

        public NamedThreadFactory(String prefix) {
            this.prefix = prefix;
        }

        @Override
        public Thread newThread(Runnable r) {
            Thread t = new Thread(r, prefix + "-" + counter.getAndIncrement());
            t.setDaemon(false);
            return t;
        }
    }
}
